/* prog47_circular_queue.c
 *
 * Re‑implementation of the original binary’s functionality.
 * The program implements a circular queue of capacity 5 that is
 * manipulated via command‑line arguments.
 *
 * Supported commands (one per argument):
 *
 *   ENQ<number>   – enqueue the signed decimal integer <number>.
 *                   Prints  "ENQ %ld" on success,
 *                   "FULL" if the queue already contains 5 items,
 *                   "ERR"  if the number cannot be parsed.
 *
 *   D             – dequeue the element at the front of the queue.
 *                   Prints  "DEQ %ld" on success,
 *                   "EMPTY" if the queue is empty.
 *
 *   F             – show the element at the front without removing it.
 *                   Prints  "FRONT %ld" on success,
 *                   "EMPTY" if the queue is empty.
 *
 *   (no arguments) – prints "NOOP".
 *
 * All output ends with a newline, exactly matching the original binary.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define CAPACITY 5

int main(int argc, char *argv[])
{
    static long items[CAPACITY];
    int head = 0;      /* index of the first element */
    int count = 0;     /* number of elements currently stored */

    if (argc < 2) {
        puts("NOOP");
        return 0;
    }

    for (int i = 1; i < argc; ++i) {
        char *cmd = argv[i];

        /* ENQ command: starts with 'E' followed by a decimal number */
        if (cmd[0] == 'E' && cmd[1] != '\0') {
            char *endptr;
            long val = strtol(cmd + 1, &endptr, 10);

            /* parsing must consume the whole remainder of the string */
            if (*endptr != '\0') {
                puts("ERR");
                continue;
            }

            if (count == CAPACITY) {
                puts("FULL");
                continue;
            }

            /* enqueue */
            items[(head + count) % CAPACITY] = val;
            ++count;
            printf("ENQ %ld\n", val);
            continue;
        }

        /* DEQ command: exactly "D" */
        if (strcmp(cmd, "D") == 0) {
            if (count == 0) {
                puts("EMPTY");
            } else {
                long val = items[head];
                head = (head + 1) % CAPACITY;
                --count;
                printf("DEQ %ld\n", val);
            }
            continue;
        }

        /* FRONT command: exactly "F" */
        if (strcmp(cmd, "F") == 0) {
            if (count == 0) {
                puts("EMPTY");
            } else {
                long val = items[head];
                printf("FRONT %ld\n", val);
            }
            continue;
        }

        /* Any other argument is considered invalid */
        puts("ERR");
    }

    return 0;
}
